The `normalizeBlocker` function should defensively handle nullish inputs by falling back to an empty object before property reads, rather than relying on repeated optional chaining. Please also ensure there is regression test coverage for null or default states.

```suggestion
function normalizeBlocker(blocker) {
  const safeBlocker = blocker || {};
  const blockerId = safeBlocker.blocker_id ?? 'unknown_blocker';
  return {
    blocker_id: blockerId,
    blocker_class: safeBlocker.blocker_class ?? blockerClass(blockerId),
    blocker_scope: safeBlocker.blocker_scope ?? null,
    blocks_question_availability: safeBlocker.blocks_question_availability === true,
    blocks_student_display: safeBlocker.blocks_student_display === true,
    status: safeBlocker.status ?? null,
    note: safeBlocker.note ?? null,
  };
}
```

